"""SimplifyAgent: slim reciprocal agent. Anchor, steady matched concessions, RFQ round-robin, one sheet per message.

Closing, must-have and pin helpers are shared with reciprocal.py."""

import math

from ..cost import complete_offer, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import closing_move, latest, moves_left
from .reciprocal import (
    ANCHOR,
    ANCHOR_FLOOR,
    FRAC0,
    FRAC_MAX,
    FRAC_STEP,
    KEEP,
    MATCH,
    MIN_STEP,
    MOVING_MIN,
    _c_alt,
    _live,
    _mine,
    _pinned,
    _sup,
    _tick,
    _valid,
    closing_accept,
)


class SimplifyAgent:
    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min(ANCHOR * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    def _sheets(self, case, events, std, theirs):
        p, pins = theirs["unit_price"], _pinned(events)
        base = {k: v for k, v in {**{f: std[f] for f in case["negotiable"] if f in std}, **theirs}.items() if v is not None}
        opts = case.get("term_options") or {}
        c_alt = _c_alt(case)
        sent = [m["term_sheets"] for m in _mine(events) if m.get("term_sheets")]
        seen = [s["terms"] for ss in sent for s in ss]

        def make(price, **over):
            over = {k: v for k, v in over.items() if k not in pins}
            return satisfy_must_haves(case, {**base, "unit_price": round(price, 2), **over}, std)

        def cost(t):
            return total_cost(case, t, std)

        def cap(t):  # hard floor: never offer a sheet that costs more than the alternative
            if (c := cost(t)) >= c_alt:
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - c
                if slope > 0:
                    t = {**t, "unit_price": round(t["unit_price"] - (c - c_alt) / slope - 0.01, 2)}
            return t

        def best_months(price, **over):
            months = [m for m in opts.get("contract_months", []) if m and "contract_months" in case["negotiable"]] or [None]
            return min(months, key=lambda m: (cost(make(price, **over, **({"contract_months": m} if m else {}))), m or 0))

        fields = [f for f in ("payment_days",) if f in case["negotiable"] and f not in pins and opts.get(f)]
        asks = [{}]
        for f in fields:
            asks = [{f: o} for o in opts[f]]

        def one(price):  # one sheet: cheapest allowed payment option and contract length
            months = best_months(price)
            return min((cap(make(price, **({"contract_months": months} if months else {}), **v)) for v in asks), key=cost)

        price = self._price(case, events, p)
        main = one(price)
        floor = max((x["terms"]["unit_price"] for ss in sent for x in ss[:1] if x["terms"].get("unit_price")), default=0.0)
        while (main in seen or main["unit_price"] <= floor) and price < p:  # always a visible step, never a repeat, never above theirs
            price = min(p, price + _tick(p))
            new = one(price)
            if new == main:  # capped: the price cannot move
                break
            main = new
        return [] if main in seen else [complete_offer(case, main)]

"""The Reciprocal Bargainer: moves a visible step every round, in step with the supplier, and closes.

Why (30 real practice runs): suppliers answer visible moves with moves and send `final_offer` when
we idle (anchors ~20% below their price that then crept 0.01-0.03 a round scored 0.03-0.1), while an
agent that moved +2-3 EUR every round scored 0.94. And one run lost a 28.00 / 30 d / lead 35 deal
(best, must-have met) by re-asking for 90 days until the supplier walked: score 0.

- `closing_accept` (reusable; `ClosingAgent(delegate)` adds it to any agent): evaluate EVERY sheet of
  every live thread (alternatives `offer:..-a` too) with total_cost; take the cheapest that keeps the
  must-haves, beats the case alternative and is no worse than the thread's opening quote; accept it
  when the supplier says final_offer/agreed, or met our last price, or repeated itself (after >= 3 of
  our messages), or it is our last allowed message.
- `ReciprocalAgent`: anchor at 0.80 x their best standing price (0.75 floor, never above our current
  price when they ask for more), then every round close 25% (rising by 5 points a round, cap 50%) of the
  gap to their best standing price, at least 1% of price (while they move: at most 0.25 x their last
  move, at least 0.2%: the local simulator pays for patience, real suppliers for visible steps), but not closer than 3% to it before the last
  two messages (the supplier then ends with final_offer and we accept); never the same sheet twice; two sheets per
  message (main: the best contract length, payment and index option we may ask; variant: their own
  payment / index terms at the same price).
"""

import logging
import math
import re

from ..cost import complete_offer, must_haves_ok, total_cost
from ..docs import standard_terms
from ..guard import satisfy_must_haves
from ..play import ENDED, closing_move, latest, moves_left, standing

log = logging.getLogger("arena")

ANCHOR, ANCHOR_FLOOR = 0.80, 0.75  # first offer: x their best standing price (0.90 was met at once in 3 real runs)
FRAC0, FRAC_STEP, FRAC_MAX, MIN_STEP = 0.25, 0.05, 0.50, 0.01
KEEP = 0.05  # stay this far below their price until the last two messages (they end with final_offer, we accept)
MOVING_MIN = 0.002  # smallest step (x price) while they move; MIN_STEP when they hold still
MATCH = 0.25  # while they move, our step is at most this x their last move
REPEAT_AFTER = 3  # our messages before "the supplier repeated its sheet twice" means it has stalled
LIMIT = re.compile(r"(?:limit|stick to|only with|stay at|must stay|have to)[^.\n]{0,40}?(\d+)\s*days", re.I)
PAYMENT = re.compile(r"\b(?:payment|net|zahlungsziel)\b", re.I)
SENTENCE = re.compile(r"[.!?\n](?!\d)")  # not the point of 28.00
PINNABLE = ("payment_days", "lead_time_days", "contract_months")


def _tick(price):
    """The smallest visible price step: a cent, or 0.1% of the price when prices are large (per 100 / 1000 pieces)."""
    return max(0.01, 0.001 * price)


def _sup(events):
    return [m for m in events if m.get("from") != "buyer"]


def _mine(events):
    return [m for m in events if m.get("from") == "buyer"]


def _sheets(events):
    """Sheets of the supplier's newest message that has any (look back past question-only replies)."""
    return next((m["term_sheets"] for m in reversed(_sup(events)) if m.get("term_sheets")), [])


def _live(threads):
    """Threads with a supplier message that have not ended."""
    return [s for s, ev in threads.items() if _sup(ev) and latest(ev).get("status") not in ENDED]


def _c_alt(case):
    alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
    return total_cost(case, alt) if alt.get("unit_price") else math.inf


def case_c_open(case, threads):
    """C of the best opening: the cheapest first-message sheet (alternatives too) of ANY thread, ended
    ones included, that keeps the must-haves. A deal must beat it: a deal worse than the opening scores 0."""
    out = math.inf
    for ev in threads.values():
        first = next((m["term_sheets"] for m in _sup(ev) if m.get("term_sheets")), [])
        std = standard_terms(ev)
        for s in first:
            t = s.get("terms") or {}
            if t.get("unit_price") is not None and must_haves_ok(case, t, std):
                out = min(out, total_cost(case, t, std))
    return out


def _valid(case, events, std, c_alt, musts=True):
    """[(C, sheet)] of the thread's standing sheets that keep the must-haves (unless musts=False), beat the alternative."""
    out = []
    for s in _sheets(events):
        t = s.get("terms") or {}
        if t.get("unit_price") is not None and s.get("term_sheet_id") and (not musts or must_haves_ok(case, t, std)):
            if (c := total_cost(case, t, std)) < c_alt:
                out.append((c, s))
    return out


def _ready(case, events, sheet):
    if latest(events).get("status") in ("final_offer", "agreed") or moves_left(case, events) <= 1:
        return True
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if not mine:
        return False
    price = sheet["terms"]["unit_price"]
    if price <= max(s["terms"].get("unit_price") or 0 for s in mine[-1]["term_sheets"]):
        return True  # they met us
    sup = [[s["terms"] for s in m["term_sheets"]] for m in _sup(events) if m.get("term_sheets")]
    return len(mine) >= REPEAT_AFTER and len(sup) >= 2 and sup[-1] == sup[-2]  # every sheet repeated, alternatives too


def _copy_sheet(case, events, std, sheet):
    """Our own term sheet with exactly the terms of one of theirs (to make it the standing sheet)."""
    base = {k: std[k] for k in case["negotiable"] if k in std}
    return complete_offer(case, {**base, **sheet["terms"]})


def _all_heard(case, threads):
    """Several live suppliers: each has had 2 of our messages, or is final / agreed, or is nearly out of messages."""
    live = _live(threads)
    return len(live) < 2 or all(
        len(_mine(threads[s])) >= 2 or latest(threads[s]).get("status") in ("final_offer", "agreed") or moves_left(case, threads[s]) <= 1
        for s in live
    )


def closing_accept(case, threads, c_open=None):
    """The decision that closes on the cheapest acceptable sheet when the rule says so, else None: an accept of
    the thread's standing sheet, or, when the best sheet is another one (an alternative `-a`, or one before a
    question-only reply), our term sheet with its exact terms - the supplier then agrees on a standing sheet."""
    c_alt, best, order = _c_alt(case), None, {s: i for i, s in enumerate(threads)}
    if not _all_heard(case, threads):
        return None
    c_open = case_c_open(case, threads) if c_open is None else c_open
    for sid in _live(threads):
        ev = threads[sid]
        for c, s in _valid(case, ev, standard_terms(ev), c_alt):
            if s["term_sheet_id"] != standing(ev)[0] and moves_left(case, ev) <= 1:
                continue  # our last message: only a standing sheet can still be accepted (a copy would be swapped away)
            if c < c_open:
                cand = (c, order[sid], sid, s["term_sheet_id"])  # ties: the thread that arrived first
                best = min(best or cand, cand)
    if best is None:
        return None
    _, _, sid, sheet_id = best
    events = threads[sid]
    sheet = next(s for s in _sheets(events) if s["term_sheet_id"] == sheet_id)
    if not _ready(case, events, sheet):
        return None
    if sheet_id == standing(events)[0]:
        return {"supplier_id": sid, "message": {"action": {"type": "accept", "term_sheet_id": sheet_id}}}
    copy = _copy_sheet(case, events, standard_terms(events), sheet)
    if any(s["terms"] == copy for m in _mine(events) for s in m.get("term_sheets") or []):
        return None  # sent already and not agreed: let the agent carry on
    return {"supplier_id": sid, "message": {"subject": case.get("title", "Our proposal"), "body": "We accept these terms; please confirm.", "term_sheets": [{"terms": copy}]}}


class ClosingAgent:
    """Adds only the accept rule to any agent."""

    def __init__(self, delegate):
        self.delegate = delegate

    def __getattr__(self, name):
        if name == "delegate":
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        try:
            if accept := closing_accept(case, threads):
                return accept
        except Exception:
            log.exception("%s closing rule failed", case.get("case_id"))
        return self.delegate.decide(case, threads)


def _pinned(events):
    """Terms the supplier will not move: repeated by it twice while we asked otherwise, or stated as a limit."""
    pins = {}
    sup = [m["term_sheets"][0]["terms"] for m in _sup(events) if m.get("term_sheets")]
    mine = [m for m in _mine(events) if m.get("term_sheets")]
    if len(sup) >= 2 and mine:
        for f in PINNABLE:
            asked = {s["terms"].get(f) for s in mine[-1]["term_sheets"]} - {None, sup[-1].get(f)}
            if sup[-1].get(f) is not None and sup[-1].get(f) == sup[-2].get(f) and asked:
                pins[f] = sup[-1][f]
    for m in _sup(events)[-2:]:
        for sentence in SENTENCE.split(m.get("body") or ""):
            if (hit := LIMIT.search(sentence)) and PAYMENT.search(sentence):
                pins["payment_days"] = int(hit.group(1))
    return pins


class ReciprocalAgent:
    def decide(self, case, threads):
        if not _live(threads):  # nothing to answer
            return {"supplier_id": next(iter(threads), None), "message": {"action": {"type": "walk_away"}}}
        if accept := closing_accept(case, threads):
            return accept
        live = [s for s in _live(threads) if moves_left(case, threads[s]) >= 1]
        open_ = [s for s in live if latest(threads[s]).get("status") not in ("final_offer", "agreed")]
        if not open_:
            return closing_move(case, threads)

        def key(s):  # keep every thread moving: fewest messages first, then the cheapest
            ev = threads[s]
            c = min((c for c, _ in _valid(case, ev, standard_terms(ev), math.inf, musts=False)), default=math.inf)
            return len(_mine(ev)), c

        sid = min(open_, key=key)
        events = threads[sid]
        std = standard_terms(events)
        valid = _valid(case, events, std, math.inf) or _valid(case, events, std, math.inf, musts=False)  # a must-have breach is fixed in our sheet
        if not valid:  # no priced sheet to answer: ask for one, give up after 3 asks
            if len(_mine(events)) >= 3:
                return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}
            return {"supplier_id": sid, "message": {"subject": case.get("title", "Our enquiry"), "body": "Could you please send us your quote?"}}
        _, best = min(valid, key=lambda v: v[0])
        sheets = self._sheets(case, events, std, best["terms"])
        if not sheets:  # nothing new left to offer: close on the best sheet, or give up
            return closing_move(case, threads)
        return {
            "supplier_id": sid,
            "message": {
                "subject": case.get("title", "Our proposal"),
                "body": "Thank you for your offer. We have moved on our side; please see our updated terms.",
                "term_sheets": [{"terms": t} for t in sheets],
            },
        }

    @staticmethod
    def _their_move(events):
        """How far the supplier's best price fell in its last message (0 if it did not)."""
        ps = [min(s["terms"]["unit_price"] for s in m["term_sheets"] if s["terms"].get("unit_price") is not None)
              for m in _sup(events) if any(s["terms"].get("unit_price") is not None for s in m["term_sheets"])]
        return max(0.0, ps[-2] - ps[-1]) if len(ps) >= 2 else 0.0

    def _price(self, case, events, p):
        mine = [m["term_sheets"][0]["terms"]["unit_price"] for m in _mine(events) if m.get("term_sheets") and m["term_sheets"][0]["terms"].get("unit_price")]
        if not mine:
            cur = case["buyer"].get("current_unit_price") or p
            return max(ANCHOR_FLOOR * p, min(ANCHOR * p, cur))  # anchor; never pay more than now unless forced
        frac = min(FRAC_MAX, FRAC0 + FRAC_STEP * len(mine))
        move = self._their_move(events)
        step = max(frac * (p - mine[-1]), MIN_STEP * p, _tick(p))
        if move > 0:  # they moved: answer in step, not beyond (a supplier that holds still gets the full step)
            step = max(MOVING_MIN * p, _tick(p), min(step, MATCH * move))
        top = p if moves_left(case, events) <= 2 else p * (1 - KEEP)
        return max(mine[-1], min(top, mine[-1] + step))

    @staticmethod
    def _index_variant(case, main, p, opts, pins, make, cost, cap, seen):
        """An index clause is security for the supplier, not cash: offer it for the price at which our C is just
        below the main sheet's C (the clause's expected cost per unit taken off the price). None if not negotiable."""
        if "index_clause" not in case["negotiable"] or "index_clause" in pins:
            return None
        best = None
        for clause in (c for c in opts.get("index_clause", []) if c):
            t = make(main["unit_price"], index_clause=clause, **{f: main[f] for f in ("payment_days", "contract_months") if f in main})
            if t["index_clause"] != clause or t["index_clause"] == main.get("index_clause"):
                continue
            slope = cost({**t, "unit_price": t["unit_price"] + 1}) - cost(t)
            if slope <= 0:
                continue
            price = round(max(0.75 * p, min(p, t["unit_price"] - (cost(t) - cost(main)) / slope - 0.01)), 2)  # no lowball
            v = cap({**t, "unit_price": price})
            if 0 < price and v not in seen and cost(v) < cost(main) and (best is None or v["unit_price"] > best["unit_price"]):
                best = v
        return best

    def _sheets(self, case, events, std, theirs):
        p, pins = theirs["unit_price"], _pinned(events)
        base = {k: v for k, v in {**{f: std[f] for f in case["negotiable"] if f in std}, **theirs}.items() if v is not None}
        opts = case.get("term_options") or {}
        c_alt = _c_alt(case)
        sent = [m["term_sheets"] for m in _mine(events) if m.get("term_sheets")]
        seen = [s["terms"] for ss in sent for s in ss]

        def make(price, **over):
            over = {k: v for k, v in over.items() if k not in pins}
            return satisfy_must_haves(case, {**base, "unit_price": round(price, 2), **over}, std)

        def cost(t):
            return total_cost(case, t, std)

        def cap(t):  # hard floor: never offer a sheet that costs more than the alternative
            if (c := cost(t)) >= c_alt:
                slope = cost({**t, "unit_price": t["unit_price"] + 1}) - c
                if slope > 0:
                    t = {**t, "unit_price": round(t["unit_price"] - (c - c_alt) / slope - 0.01, 2)}
            return t

        def best_months(price, **over):
            months = [m for m in opts.get("contract_months", []) if m and "contract_months" in case["negotiable"]] or [None]
            return min(months, key=lambda m: (cost(make(price, **over, **({"contract_months": m} if m else {}))), m or 0))

        fields = [f for f in ("payment_days", "index_clause") if f in case["negotiable"] and f not in pins and opts.get(f)]
        combos = [{}]
        for f in fields:
            combos = [{**v, f: o} for v in combos for o in opts[f]]

        def pair(price):
            """(main, variant): main asks for the cheapest payment/index option, variant keeps their own."""
            months = best_months(price)
            mk = lambda v: cap(make(price, **({"contract_months": months} if months else {}), **v))  # noqa: E731
            theirs, asks = mk({}), [mk(v) for v in combos]
            main = min(asks, key=cost)
            return main, theirs

        price = self._price(case, events, p)
        main, theirs = pair(price)
        floor = max((x["terms"]["unit_price"] for ss in sent for x in ss[:1] if x["terms"].get("unit_price")), default=0.0)
        while (main in seen or main["unit_price"] <= floor) and price < p:  # always a visible step, never a repeat, never above theirs
            price = min(p, price + _tick(p))
            new, theirs = pair(price)
            if new == main:  # capped: the price cannot move
                break
            main = new
        if main in seen:
            return []
        out = [main] + ([theirs] if theirs != main and theirs not in seen else [])
        if (extra := self._index_variant(case, main, p, opts, pins, make, cost, cap, seen)) and extra not in out:
            out.append(extra)
        return [complete_offer(case, t) for t in out]

"""Evidence wrapper: lets any agent decide, then rewrites each 'send' into a short business e-mail that
cites verified data (see evidence.py): up to 3 new claims, one question, refs set to the cited IDs.
Term sheets, accept and walk-away decisions are untouched; any failure keeps the delegate's decision."""

import logging
import re

from ..cost import OPS
from ..evidence import build_claims, load_package
from ..play import live_threads, standing

log = logging.getLogger("arena")

MAX_CLAIMS, MAX_WORDS = 3, 160
ID = re.compile(r"\b(?:idx|quote|sc|qn|po|fc|cost|news|doc|ctr|offer):[\w@.#-]*\w")
FIELDS = {"volume_per_year": "lift your allocation to {v} units per year"}


def _cited(events):
    """Every data ID our messages in a thread already cite (refs and body)."""
    return {i for m in events if m.get("from") == "buyer" for i in [*(m.get("refs") or []), *ID.findall(m.get("body") or "")]}


class EvidenceAgent:
    def __init__(self, delegate, data=None):
        self.delegate, self.data, self._pkg, self._loaded = delegate, data, None, False

    def __getattr__(self, name):  # e.g. `.chosen` of a wrapped router
        if name in ("delegate", "data", "_pkg", "_loaded"):
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        decision = self.delegate.decide(case, threads)
        try:
            msg, sid = decision.get("message") or {}, decision.get("supplier_id")
            if msg.get("action") or sid not in threads or not threads[sid]:
                return decision
            if not self._loaded:
                self._loaded = True
                self._pkg = load_package(self.data)
            if self._pkg is None:
                return decision
            return {**decision, "message": self._rewrite(case, threads, sid, msg)}
        except Exception:
            log.exception("%s evidence: failed, keeping the delegate's message", case.get("case_id"))
            return decision

    def _rewrite(self, case, threads, sid, msg):
        events = threads[sid]
        _, terms = standing(events)
        price = terms.get("unit_price")
        used = set().union(*(_cited(e) for e in threads.values()))
        used = {i for i in used if not i.startswith("offer:")} | {i for i in _cited(events) if i.startswith("offer:")}
        claims = [c for c in build_claims(case, self._pkg, sid, price) if not used & set(c["ids"])]
        asks = []
        for m in case["buyer"].get("must_haves", []):
            cur = terms.get(m["field"])
            if cur is not None and not OPS[m["op"]](cur, m["value"]):
                what = FIELDS.get(m["field"]) or f"confirm {m['field'].replace('_', ' ')} {'of at least' if '>' in m['op'] else 'of at most'} {{v}}"
                asks.append(f"Could you {what.format(v=m['value'])}?")
                if m["field"] == "volume_per_year":
                    claims.sort(key=lambda c: c["kind"] != "fc")  # the forecast backs a volume ask (stable sort)
        rivals = [(standing(threads[o])[1].get("unit_price"), standing(threads[o])[0]) for o in live_threads(threads) if o != sid]
        rivals = [r for r in rivals if r[0] is not None and r[1] and price is not None and r[0] < price]
        if rivals and len(case.get("parts", [])) == 1 and not any(i.startswith("offer:") for i in _cited(events)):
            p, oid = min(rivals)
            claims.insert(0, {"kind": "offer", "ids": [oid], "strength": 90, "sentence": f"Another bidder's offer for this part stands at EUR {p:.2f} per unit ({oid})."})
        picked, ids = [], set()
        for c in claims:
            if c["kind"] != "calc" and len([x for x in picked if x["kind"] != "calc"]) < MAX_CLAIMS and not ids & set(c["ids"]):
                picked.append(c)
                ids |= set(c["ids"])
        calc = [c for c in claims if c["kind"] == "calc"]
        if calc and any(c["kind"] == "idx" for c in picked):
            picked.append(calc[0])
        picked.sort(key=lambda c: -c["strength"])
        theirs = [m for m in events if m.get("from") != "buyer"]
        last = theirs[-1]
        if not any(m.get("term_sheets") for m in theirs):
            asks.append("Could you please send us your quote?")
        elif sum(m.get("from") == "buyer" for m in events) == 0:
            asks.append("Could you send us a breakdown of the costs behind your price?")
        elif last.get("status") == "final_offer" or re.search(r"\b(limit|cap|allocation)", last.get("body") or "", re.I):
            asks.append("Could you explain the reason behind the limit you stated?")
        sheets = bool(msg.get("term_sheets"))
        company = re.search(r"for ([A-Z][\w&. -]+?) (?:with|from)", case.get("briefing", ""))
        sign = f"{company.group(1)}, Purchasing" if company else "Purchasing"
        subject = (msg.get("subject") or "Re: " + (last.get("subject") or case.get("title", "our enquiry")))[:300]

        def body(cs, qs):
            return "\n".join(["Dear Sir or Madam,", "", "thank you for your message." + (" Our proposed terms are in the term sheet of this message." if sheets else ""),
                              *[c["sentence"] for c in cs], *qs, "", "Best regards,", sign])

        qs = list(asks)
        while len(body(picked, qs).split()) > MAX_WORDS and (picked or len(qs) > 1):
            if picked:
                picked.pop()
            else:
                qs.pop()
        return {**msg, "subject": subject, "body": body(picked, qs), "refs": [i for c in picked for i in c["ids"]]}

"""Guard layer: wraps any delegate agent so a must-have is always ASKED for in the term sheet and an
open thread is never abandoned while something sensible is left to try.

Why: practice runs lost cases with no deal because sheets were snapped (by `complete_offer`) onto
an option that breaks a must-have, and the agents then walked away. `satisfy_must_haves` fixes the
sheets; `GuardedAgent` turns a delegate's walk-away (or crash) into an accept of a safe standing
sheet, or into one more counter at the supplier's own price with the must-haves satisfied.
"""

import logging

from .cost import OPS, complete_offer, must_haves_ok, snap, total_cost
from .docs import standard_terms
from .play import ENDED, closing_move, latest, live_threads, moves_left, standing

log = logging.getLogger("arena")

MAX_COUNTERS = 2  # guard counters per thread and case
EARLY_ACCEPT = 0.97  # accept a safe sheet before the last move only once the supplier has moved this far
ASK_QUOTE = "Could you please send us your quote?"
ASK_BODY = "We can proceed at your price if the terms below work for you; please confirm."


def _fits(m, value):
    try:
        return value is not None and OPS[m["op"]](value, m["value"])
    except TypeError:
        return False


def _must_have_value(case, m, current):
    """A value for the must-have's field that satisfies it, or `current` when none can."""
    op, bound = m["op"], m["value"]
    options = [o for o in (case.get("term_options") or {}).get(m["field"]) or [] if o is not None]
    if options:
        ok = [o for o in options if _fits(m, o)]
        if not ok:
            return current
        if op in ("<=", "<"):
            return max(ok)
        if op in (">=", ">"):
            return min(ok)
        if op == "!=":
            return current if _fits(m, current) else ok[0]
        return bound
    if op in ("<=", ">=", "=="):
        return bound
    if op == "!=":
        return current if _fits(m, current) else (bound + 1 if isinstance(bound, int | float) else current)
    step = 1 if isinstance(bound, int) else 0.01
    return bound - step if op == "<" else bound + step


def satisfy_must_haves(case, terms, standard=None):
    """A copy of `terms` with every must-have on a negotiable field satisfied, completed to a valid
    sheet. Must-haves on fields we cannot negotiate are left alone."""
    must = [m for m in case["buyer"].get("must_haves", []) if m["field"] in case["negotiable"]]
    result = dict(terms)
    for m in must:
        cur = result.get(m["field"])
        cur = snap(case, m["field"], cur) if cur is not None else cur  # complete_offer snaps it later
        result[m["field"]] = cur if _fits(m, cur) else _must_have_value(case, m, cur)
    result = complete_offer(case, result)
    for m in must:  # a gap filled from the plan, or a snap, may have broken it again
        if not _fits(m, result.get(m["field"])):
            result[m["field"]] = _must_have_value(case, m, result.get(m["field"]))
    if not must_haves_ok(case, result, standard):
        log.debug("guard: must-haves still fail after fixing %s", result)
    return result


def fix_sheets(case, sheets, standard=None):
    """(sheets, changes): `satisfy_must_haves` on each sheet (other keys kept); exact duplicates
    dropped; at most 3 kept. `changes`: what was changed, per input sheet, as readable text."""
    out, changes = [], []
    for s in sheets:
        old = s.get("terms") or {}
        fixed = {**s, "terms": satisfy_must_haves(case, old, standard)}
        if c := ", ".join(f"{k} {old.get(k)} -> {v}" for k, v in fixed["terms"].items() if old.get(k) != v):
            changes.append(c)
        if fixed not in out:
            out.append(fixed)
    return out[:3], changes


def _text(sid, body, sheets=None):
    msg = {"subject": "Our proposal", "body": body}
    if sheets:
        msg["term_sheets"] = sheets
    return {"supplier_id": sid, "message": msg}


def _walk(sid):
    return {"supplier_id": sid, "message": {"action": {"type": "walk_away"}}}


class GuardedAgent:
    def __init__(self, delegate, log_name="arena"):
        self.delegate = delegate
        self.log = logging.getLogger(log_name)
        self._case_id = None
        self._tried = {}

    def __getattr__(self, name):  # e.g. `.chosen` of a wrapped router
        if name in ("delegate", "log", "_case_id", "_tried"):
            raise AttributeError(name)
        return getattr(self.delegate, name)

    def decide(self, case, threads):
        """Never raises: any failure here falls back to the guard's own continuation, then closing_move."""
        if not any(threads.values()):  # nothing to look at: nothing to continue
            return _walk(next(iter(threads), None))
        try:
            return self._decide(case, threads)
        except Exception:
            log.exception("%s guard: failed", self._case_id)
        try:
            return self._keep_going(case, threads, None, "guard failed")
        except Exception:
            log.exception("%s guard: fallback failed", self._case_id)
        try:
            return closing_move(case, threads)
        except Exception:
            return _walk(next(iter(threads), None))

    def _decide(self, case, threads):
        if case.get("case_id") != self._case_id:
            self._case_id, self._tried = case.get("case_id"), {}
        error = False
        try:
            decision = self.delegate.decide(case, threads)
        except Exception:
            log.exception("%s guard: delegate crashed", self._case_id)
            decision, error = None, True
        msg = (decision or {}).get("message") or {}
        action = msg.get("action") or {}
        sid = (decision or {}).get("supplier_id")
        if decision and action.get("type") == "accept":
            if self._accept_ok(case, threads, decision):
                events = threads[sid]
                if (not any(m.get("from") == "buyer" for m in events) and moves_left(case, events) > 1
                        and not self._supplier_moved(case, threads, sid)):
                    self.log.info("%s guard: deferred round-1 accept on %s (unmoved opening offer)",
                                  self._case_id, sid)
                    return self._counter(case, threads, sid)
                return decision
            return self._keep_going(case, threads, sid, "delegate accept is not safe")
        if decision and msg.get("term_sheets"):
            sheets = self._fix(case, threads, sid, msg["term_sheets"])
            if sheets:
                return self._last_move(case, threads, {**decision, "message": {**msg, "term_sheets": sheets}})
        elif decision and not action:
            return self._last_move(case, threads, decision)  # a text-only message
        reason = (
            "delegate crashed" if error
            else "delegate wanted to walk" if action.get("type") == "walk_away"
            else f"unknown action {action.get('type')}" if action
            else "no usable sheet"
        )
        return self._keep_going(case, threads, sid, reason)

    @staticmethod
    def _accept_ok(case, threads, decision):
        """The accept names the standing sheet, keeps the must-haves and beats the alternative."""
        sid, action = decision.get("supplier_id"), decision["message"]["action"]
        if sid not in threads or latest(threads[sid]).get("status") in ENDED:
            return False
        sheet_id, terms = standing(threads[sid])  # only the standing id: an `-a` id is not verified to be accepted
        if sheet_id is None or sheet_id != action.get("term_sheet_id"):
            return False
        std = standard_terms(threads[sid])
        if not must_haves_ok(case, terms, std):
            return False
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        return not alt.get("unit_price") or total_cost(case, terms, std) < total_cost(case, alt)

    def _fix(self, case, threads, sid, sheets):
        std = standard_terms(threads[sid]) if sid in threads else {}
        fixed, changes = fix_sheets(case, sheets, std)
        for c in changes:
            self.log.info("%s guard: fixed sheet (must-have): %s", self._case_id, c)
        return fixed

    def _last_move(self, case, threads, decision):
        """Rule e: on our last allowed message, a price push the supplier will refuse is replaced."""
        sid = decision["supplier_id"]
        if sid not in threads:
            return decision
        left = moves_left(case, threads[sid])
        if left > 1:
            return decision
        if left < 1:
            self.log.info("%s guard: closing move (no messages left on %s)", self._case_id, sid)
            return closing_move(case, threads)
        sheets = decision["message"].get("term_sheets") or []
        theirs = standing(threads[sid])[1].get("unit_price")
        prices = [p for p in (s["terms"].get("unit_price") for s in sheets) if p is not None]
        if theirs is None or not prices or min(prices) >= theirs:
            return decision
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "accept":
            self.log.info("%s guard: accept on last move (a lower counter would be refused)", self._case_id)
            return close
        self.log.info("%s guard: must-have counter at their price on last move", self._case_id)
        return self._counter(case, threads, sid)

    def _counter(self, case, threads, sid):
        events = threads[sid]
        _, terms = standing(events)
        if terms.get("unit_price") is None:
            body = _text(sid, ASK_QUOTE)
        else:
            sheet = satisfy_must_haves(case, dict(terms), standard_terms(events))
            body = _text(sid, ASK_BODY, [{"terms": sheet}])
        key = (self._case_id, sid)
        self._tried[key] = self._tried.get(key, 0) + 1
        return body

    def _eligible(self, case, threads, sid):
        events = threads[sid]
        status, left = latest(events).get("status"), moves_left(case, events)
        cap = 1 if status == "final_offer" else MAX_COUNTERS
        return status not in ENDED | {"agreed"} and left >= 1 and self._tried.get((self._case_id, sid), 0) < cap

    def _supplier_moved(self, case, threads, sid):
        """The standing sheet costs at most EARLY_ACCEPT x the thread's opening sheet."""
        events = threads[sid]
        std = standard_terms(events)
        _, terms = standing(events)
        opening = next((t for m in events if m.get("from") != "buyer"
                        for sh in m.get("term_sheets") or [] for t in [sh.get("terms") or {}]
                        if t.get("unit_price") is not None), None)
        if opening is None:
            return True
        return total_cost(case, terms, std) <= EARLY_ACCEPT * total_cost(case, opening, std)

    @staticmethod
    def _hopeless(case, threads):
        """Every live thread is at its final offer (or out of messages) and even its must-have-fixed sheet costs
        no less than the alternative: a counter could only end above the alternative's C."""
        alt = (case["buyer"].get("alternative") or {}).get("terms") or {}
        if not alt.get("unit_price"):
            return False
        c_alt = total_cost(case, alt)
        for sid in live_threads(threads):
            ev = threads[sid]
            if latest(ev).get("status") != "final_offer" and moves_left(case, ev) >= 1:
                return False
            terms = standing(ev)[1]
            if terms.get("unit_price") is not None:
                std = standard_terms(ev)
                if total_cost(case, satisfy_must_haves(case, dict(terms), std), std) < c_alt:
                    return False
        return True

    def _keep_going(self, case, threads, preferred, reason):
        """Rule d: never walk while something sensible is left."""
        close = closing_move(case, threads)
        if close["message"]["action"]["type"] == "walk_away" and reason == "delegate wanted to walk" and self._hopeless(case, threads):
            self.log.info("%s guard: walk away stands (every thread is final, no counter beats the alternative)", self._case_id)
            return close
        if close["message"]["action"]["type"] == "accept":
            asid = close["supplier_id"]
            if (moves_left(case, threads[asid]) <= 1 or not self._eligible(case, threads, asid)
                    or self._supplier_moved(case, threads, asid)):
                self.log.info("%s guard: accept a safe standing sheet (%s)", self._case_id, reason)
                return close
        live = [s for s in live_threads(threads) if self._eligible(case, threads, s)]

        def cost(s):
            terms = standing(threads[s])[1]
            try:
                return total_cost(case, terms, standard_terms(threads[s])) if terms.get("unit_price") else float("inf")
            except Exception:
                return float("inf")

        order = ([preferred] if preferred in live else []) + sorted((s for s in live if s != preferred), key=cost)
        if not order:
            self.log.info("%s guard: closing move, no thread left to continue (%s)", self._case_id, reason)
            return close
        sid = order[0]
        self.log.info("%s guard: counter at their price on %s (%s)", self._case_id, sid, reason)
        return self._counter(case, threads, sid)

"""Play cases with an agent against the arena over HTTP - the hosted arena (practice, sandbox,
final) or `arena-sim`, the local contract simulator. Both speak the same API.

An agent is any object with `decide(case, threads) -> {"supplier_id": ..., "message": {...}}`:
  threads: {supplier_id: [message, ...]} - every e-mail so far, both directions, in order;
           supplier attachments carry their text under "text" (see `docs.read_document`).
  message: subject, body, up to 3 term sheets, refs - or an "action" that closes the case:
           {"type": "accept", "term_sheet_id": ...} or {"type": "walk_away"}.
"""

import copy
import functools
import logging
import re
import threading
import time
from concurrent.futures import FIRST_COMPLETED, ThreadPoolExecutor, wait

from .client import ArenaError
from .cost import must_haves_ok, total_cost
from .docs import read_document, standard_terms

log = logging.getLogger("arena")

ENDED = {"walked_away", "no_bid"}
# A message later than this after the supplier's last one counts as a timeout.
MOVE_LIMIT_S = 60
# In the Live Final, close this long before the wave's cap - or the slowest round of the case so far
# (your decision plus a supplier reply of up to about a minute) plus a margin, if that is longer.
CLOSE_BEFORE_CAP_S, ROUND_MARGIN_S = 90, 15
RUNNING = re.compile(r"one session per case in the final: (\S+)")
# Practice: the case list shows every practice case file; only those marked hosted can be played
# (a session on another is a 403). Without the marker every listed case counts as hosted.
HOSTED_FIELD = "hosted"


class RemoteTable:
    """The arena over HTTP: the practice arena, the final, or a hosted sandbox."""

    def __init__(self, client, case=None):
        self.client, self.session_id, self.case, self.done = client, None, case, None

    def open(self, case_id):
        try:
            r = self.client.open_session(case_id)
        except ArenaError as e:
            running = RUNNING.search(str(e.detail)) if e.status == 409 else None
            if not (running and self.case):
                raise
            return self.resume(running.group(1))
        self.session_id = r["session_id"]
        log.info("session %s", self.session_id)
        return r["case"], r["threads"]

    def resume(self, session_id):
        """Pick up a final session this team already started (e.g. after a crash): every thread
        so far, from the arena."""
        self.session_id = session_id
        log.info("resuming session %s", session_id)
        state = self.client.session(session_id)
        if state["status"] == "ended":
            self.done = self.result()
        return self.case, {s: self.client.thread(session_id, s)["messages"] for s in state["threads"]}

    def send(self, supplier_id, message):
        return self.client.send_message(self.session_id, supplier_id, message)

    def close(self, supplier_id, message):
        reply = self.client.send_message(self.session_id, supplier_id, message)
        return reply.get("result", reply)  # the supplier's last e-mail carries the result

    def attachment(self, attachment_id):
        return self.client.attachment(self.session_id, attachment_id)

    def missed(self, supplier_id, error):
        """After a 409: the result if the case has ended (e.g. at a wave's cap), else what the
        thread now says (a timeout answer, or the reason it ended)."""
        state = self.client.session(self.session_id)
        if state.get("status") == "ended":
            return {"result": state.get("result") or {"deal": False, "end_reason": state.get("end_reason")}}
        t = self.client.thread(self.session_id, supplier_id)
        last = (t.get("timeouts") or [{}])[-1]
        sheet = [{"term_sheet_id": t["offer_id"], "terms": last.get("terms", {})}]
        return {
            "from": "arena",
            "status": "walked_away" if t["closed"] else t["status"],
            "term_sheets": [] if t["closed"] else sheet,
            "body": f"({error.detail})",
            "missing_fields": last.get("missing_fields", []),
            "attachments": [],
        }

    def result(self):
        state = self.client.session(self.session_id)
        return state.get("result") or {"deal": False, "end_reason": state.get("end_reason"), **state}


def latest(events):
    """The supplier's latest message in a thread."""
    return next(m for m in reversed(events) if m.get("from") != "buyer")


def standing(events):
    """(term_sheet_id, terms) of the supplier's standing term sheet, or (None, {})."""
    sheets = latest(events).get("term_sheets") or []
    return (sheets[0]["term_sheet_id"], sheets[0]["terms"]) if sheets else (None, {})


def find_sheet(events, sheet_id):
    """Terms of `sheet_id` among the sheets of the supplier's newest message that has any (so its
    alternatives count, an older superseded sheet does not), or None."""
    for m in reversed(events):
        if m.get("from") != "buyer" and m.get("term_sheets"):
            return next((s["terms"] for s in m["term_sheets"] if s.get("term_sheet_id") == sheet_id), None)
    return None


def live_threads(threads):
    """Suppliers whose thread has not ended."""
    return [sid for sid, ev in threads.items() if latest(ev).get("status") not in ENDED]


def moves_left(case, events):
    """Messages you may still send in this thread (the round limit counts each of them)."""
    return case.get("round_limit", 10) - sum(m.get("from") == "buyer" for m in events)


def fetch_documents(table, message):
    """Download every attachment of a supplier message and add its text."""
    for att in message.get("attachments") or []:
        if att.get("attachment_id") and "text" not in att:
            att["text"] = read_document(att["name"], table.attachment(att["attachment_id"]))
    return message


def closing_move(case, threads, stds=None):
    """Accept the cheapest standing term sheet that keeps the must-haves and beats the alternative
    (C with each supplier's standard terms), else walk away - what to do when time runs out."""
    alt = case["buyer"].get("alternative") or {}
    c_alt = total_cost(case, alt["terms"]) if alt.get("terms", {}).get("unit_price") else float("inf")
    from .agents.reciprocal import case_c_open  # lazy: that module imports this one

    c_open, best = case_c_open(case, threads), None  # a deal worse than the opening quote scores 0 (equal: kept, it is full marks when nothing can be won)
    for sid in live_threads(threads):
        sheet_id, terms = standing(threads[sid])
        std = (stds or {}).get(sid) or standard_terms(threads[sid])
        if sheet_id and must_haves_ok(case, terms, std) and (c := total_cost(case, terms, std)) < c_alt and c <= c_open:
            best = min(best or (c, sid, sheet_id), (c, sid, sheet_id))
    if best is None:
        return {"supplier_id": live_threads(threads)[0], "message": {"action": {"type": "walk_away"}}}
    return {"supplier_id": best[1], "message": {"action": {"type": "accept", "term_sheet_id": best[2]}}}


def _safe_accept(case, threads, sid, terms):
    """The thread's standing sheet is live, keeps the must-haves and beats both the alternative and the opening."""
    from .agents.reciprocal import _c_alt, case_c_open  # lazy: that module imports this one

    ev, std = threads[sid], standard_terms(threads[sid])
    if latest(ev).get("status") in ENDED or terms.get("unit_price") is None or not must_haves_ok(case, terms, std):
        return False
    c = total_cost(case, terms, std)
    return c < _c_alt(case) and c < case_c_open(case, threads)


def cap_near(cap, slowest):
    return bool(cap) and time.time() > cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S)


def _snapshot(agent):
    """Mutable per-case state of the agent and its `delegate` chain, to undo a decision that is thrown
    away. Limits: only dict, list and set attributes are saved (tuples and scalars are not restored,
    so a stateful agent that keeps those drifts); an attribute that cannot be deep-copied is skipped."""
    out = []
    while agent is not None:
        saved = {}
        for k, v in vars(agent).items():
            if isinstance(v, (dict, list, set)):
                try:
                    saved[k] = copy.deepcopy(v)
                except Exception:
                    log.warning("%s.%s cannot be snapshotted", type(agent).__name__, k)
        out.append((agent, saved))
        agent = getattr(agent, "delegate", None)
    return out


def _restore(snap):
    for agent, state in snap:
        vars(agent).update(state)


def _open(case, threads):
    """Live threads we can still answer with a counter."""
    return [s for s in live_threads(threads) if moves_left(case, threads[s]) >= 1
            and latest(threads[s]).get("status") not in ("final_offer", "agreed")]


def play(table, case_id, agent, deadline=None):
    """Play one case to its end. `deadline` (time.time(), or a function returning it): a Live Final
    wave's cap - shortly before it, `closing_move` closes the case so it does not end without a deal.

    Every open thread gets its answer within the supplier's 60 s window: a message is chosen for each
    thread that has none in flight, all are sent at once, and each reply is merged and its thread
    answered again as soon as it arrives (not when the slowest supplier has answered). Decisions and
    merges all run in this thread, so `threads` and the agent need no lock; only `table.send` runs in workers.
    An accept or walk-away runs alone, after the replies in flight are in."""
    case, threads = table.open(case_id)
    if getattr(table, "done", None):  # resumed a case that had already ended
        return table.done
    for events in threads.values():
        for m in events:
            fetch_documents(table, m)
    slowest = 0.0  # the longest round so far: decision + the supplier's reply

    def run_action(sid, msg):
        """(True, result) when the case ended, else (False, None): the case goes on."""
        try:
            log.info("%s %s", sid, msg["action"])
            try:
                return True, table.close(sid, msg)
            except ArenaError as e:  # a refused accept id (422): retry once with the thread's standing sheet
                stand, terms = standing(threads[sid])
                if (e.status != 422 or msg["action"].get("type") != "accept" or stand in (None, msg["action"].get("term_sheet_id"))
                        or not _safe_accept(case, threads, sid, terms)):
                    raise
                log.warning("%s: accept refused (%s) - retrying with %s", sid, e.detail, stand)
                return True, table.close(sid, {"action": {"type": "accept", "term_sheet_id": stand}})
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)  # e.g. late, or the thread or the case has ended
            if "result" in reply:
                return True, reply["result"]
            threads[sid].append(fetch_documents(table, reply))
            return False, None

    def send(sid, msg):
        t1 = time.monotonic()
        try:
            reply = table.send(sid, msg)
        except ArenaError as e:
            if e.status != 409:
                raise
            log.info("%s: %s", sid, e.detail)
            reply = table.missed(sid, e)
        log.info("%s send took %.1fs", sid, time.monotonic() - t1)
        return reply

    pending, started, futures = {}, {}, {}  # sid -> our message in flight / when sent; future -> sid
    errored = {}  # sid -> the exception of its last send: left out until another thread gets a reply
    with ThreadPoolExecutor(max_workers=max(1, len(threads))) as pool:
        while pending or live_threads(threads):
            while True:  # answer every open thread that has no message in flight
                cap = deadline() if callable(deadline) else deadline
                near = cap_near(cap, slowest)
                free = [s for s in _open(case, threads) if s not in pending and s not in errored]
                if errored and not pending and not free:
                    raise next(iter(errored.values()))  # every thread failed
                if pending and not near and not free:
                    break
                t0 = time.monotonic()
                snap = _snapshot(agent) if pending and not near else None  # this decision may be thrown away
                if near:
                    log.info("%s: the wave's cap is near - closing", case_id)
                    decision = closing_move(case, threads)
                else:
                    view = {s: ev + [{**pending[s], "from": "buyer"}] if s in pending else ev
                            for s, ev in threads.items() if s not in errored}
                    decision = agent.decide(case, view)
                    if pending and not decision["message"].get("action") and decision["supplier_id"] in pending and free:
                        # the agent prefers a thread that is already in flight: choose among the others
                        _restore(snap)
                        snap = _snapshot(agent)
                        decision = agent.decide(case, {s: ev for s, ev in threads.items() if s not in pending and s not in errored})
                if (took := time.monotonic() - t0) > MOVE_LIMIT_S * 0.75:
                    log.warning("decision took %.1fs - the limit is %ss per message", took, MOVE_LIMIT_S)
                sid, msg = decision["supplier_id"], decision["message"]
                if pending and not near and (msg.get("action") or sid in pending):
                    _restore(snap)  # decided again once the replies in flight are in
                    break
                if msg.get("action"):
                    done, result = run_action(sid, msg)
                    if done:
                        return result
                    continue
                pending[sid], started[sid] = msg, t0
                futures[pool.submit(send, sid, msg)] = sid
            if not pending:
                continue
            timeout = None
            if cap := (deadline() if callable(deadline) else deadline):
                timeout = max(0.0, cap - max(CLOSE_BEFORE_CAP_S, slowest + ROUND_MARGIN_S) - time.time())
            for f in wait(futures, timeout, return_when=FIRST_COMPLETED)[0]:
                sid = futures.pop(f)
                msg = pending.pop(sid)
                try:
                    reply = f.result()
                except Exception as e:  # one failing thread must not stop the others
                    log.exception("%s: send failed", sid)
                    errored[sid] = e
                    started.pop(sid)
                    continue
                errored.clear()
                if "result" in reply:  # the reply ended the case, e.g. the last supplier walked away
                    return reply["result"]
                threads[sid] += [{**msg, "from": "buyer"}, fetch_documents(table, reply)]
                slowest = max(slowest, time.monotonic() - started.pop(sid))
                log.info("%s %s %s", sid, reply.get("status"), standing(threads[sid])[1])
    return table.result()


def hosted(cases):
    """The cases you can play: those marked hosted, or all of them if the list has no marker."""
    if any(HOSTED_FIELD in c for c in cases):
        return [c for c in cases if c.get(HOSTED_FIELD)]
    return cases


def quota_used_up(error):
    """The practice quota's 429 ("practice limit: …"): retrying does not help before it resets."""
    return isinstance(error, ArenaError) and error.status == 429 and str(error.detail).startswith("practice limit")


def play_all(new_table, case_ids, new_agent, parallel=8):
    """Play many cases at once (e.g. every practice case). `new_table()` and `new_agent()` give
    each case its own table and agent. Once the practice quota is used up, no further case starts.
    Returns {case_id: result or the exception that stopped it}."""
    used_up = threading.Event()

    def one(case_id):
        if used_up.is_set():
            return case_id, ArenaError(429, "not started: the practice quota is used up")
        try:
            return case_id, play(new_table(), case_id, new_agent())
        except ArenaError as e:
            if quota_used_up(e):
                used_up.set()
                log.warning("practice quota used up: %s", e.detail)
            elif e.status == 403:
                log.warning("%s: %s", case_id, e.detail)  # e.g. not hosted for practice
            else:
                log.exception("%s failed", case_id)
            return case_id, e
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case_id)
            return case_id, e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        return dict(pool.map(one, case_ids))


def play_waves(client, new_agent, waves=5, parallel=10, poll=5.0):
    """The Live Final: wait for each wave, play its cases in parallel within the wave's cap, wait
    for the next. Keep it running from before the first wave until the last has closed; it returns
    after `waves` waves have closed and every case has finished: {case_id: result or exception}."""
    started, closed, caps = {}, set(), {}  # caps: wave -> its cap as time.time()

    def one(case, deadline):
        try:
            return play(RemoteTable(client, case), case["case_id"], new_agent(), deadline)
        except Exception as e:  # one broken case must not stop the others
            log.exception("%s failed", case["case_id"])
            return e

    with ThreadPoolExecutor(max_workers=parallel) as pool:
        while len(closed) < waves or not all(f.done() for f in started.values()):
            try:
                cases = client.cases("final")
            except ArenaError as e:
                if e.status != 403:  # 403: no wave has started yet
                    raise
                cases = []
            for case in cases:
                if not case.get("open"):
                    closed.add(case["wave"])
                    continue
                if case.get("seconds_left") is not None:  # each wave has its own cap; follow an extension
                    caps[case["wave"]] = time.time() + case["seconds_left"]
                if case["case_id"] not in started and case.get("seconds_left"):
                    if case["wave"] not in {c["wave"] for c in cases if c["case_id"] in started}:
                        log.warning("wave %s started: %s", case["wave"], case.get("theme"))
                    started[case["case_id"]] = pool.submit(one, case, functools.partial(caps.get, case["wave"]))
            time.sleep(poll)
    return {case_id: f.result() for case_id, f in started.items()}
